import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019Q2 Ceph社区季度总结","description":"","frontmatter":{"title":"2019Q2 Ceph社区季度总结","date":"2019-6-01","tags":["Ceph","社区动态","技术发展"],"outline":"deep"},"headers":[],"relativePath":"quarterly/2019Q2_Ceph社区季度总结.md","filePath":"quarterly/2019Q2_Ceph社区季度总结.md","lastUpdated":1780459816000}'),o={name:"quarterly/2019Q2_Ceph社区季度总结.md"};function a(p,l,n,s,u,h){return i(),r("div",null,[...l[0]||(l[0]=[t('<h1 id="ceph-社区-2019q2-季度总结报告" tabindex="-1">Ceph 社区 2019Q2 季度总结报告 <a class="header-anchor" href="#ceph-社区-2019q2-季度总结报告" aria-label="Permalink to &quot;Ceph 社区 2019Q2 季度总结报告&quot;">​</a></h1><h2 id="_1-本季度-ceph-社区的主要活动和重点议题" tabindex="-1">1. 本季度 Ceph 社区的主要活动和重点议题 <a class="header-anchor" href="#_1-本季度-ceph-社区的主要活动和重点议题" aria-label="Permalink to &quot;1. 本季度 Ceph 社区的主要活动和重点议题&quot;">​</a></h2><p><strong>1.1 Ceph BenchOps：简化 Ceph 项目上线流程</strong></p><ul><li>由加州大学圣克鲁兹分校的 Eva Jimenez 博士研究生主持。</li><li>旨在简化学生使用 Ceph（安全存储）的上线和部署流程。</li><li>使用 GitHub Action 工作流程和容器化技术来简化流程，提高效率和用户体验。</li></ul><p><strong>1.2 探索 Nautilus 中 Surface 的性能限制</strong></p><ul><li>由 Red Hat 的 Manoj Pillai 介绍。</li><li>探讨了 Nautilus 版本中 Surface 的 I/O 性能限制。</li><li>测试结果表明，Surface 在顺序 I/O 和随机读方面表现出色，但随机写和小型文件 I/O 性能较差。</li></ul><p><strong>1.3 Crimson SeaStor OSD 周会</strong></p><ul><li>讨论了 Ceph 项目进展、性能测试、代码审查及后续行动计划。</li><li>包括 Crimson 项目进展、测试方法、性能改进和代码审查等方面。</li></ul><p><strong>1.4 Per OSD Recovery Bandwidth Control Based on dmClock</strong></p><ul><li>由 ZTE 公司的 Xie Xingguo 和 Yan Jun 介绍。</li><li>提出了基于 dmClock 的云附加存储方法设计、实现和测试。</li><li>通过控制去重操作的带宽，平衡去重与客户端性能之间的关系。</li></ul><p><strong>1.5 Ceph 对象存储在公共云服务中的应用</strong></p><ul><li>由 China Mobile 的 Yu Liyang 介绍。</li><li>讨论了 Ceph 对象存储在公共云服务中的应用，包括集群扩展、W 模块更新和性能压力。</li></ul><p><strong>1.6 Failing Better - When Not To Ceph and Lessons Learned</strong></p><ul><li>由 SUSE 的 Lars Marowsky-Brée 介绍。</li><li>讨论了 Ceph 的限制和约束，以及如何根据实际需求选择合适的硬件和网络。</li></ul><p><strong>1.7 Unlimited Fileserver with Samba CTDB and CephFS</strong></p><ul><li>由 Heinlein Support GmbH 的 Robert Sander 介绍。</li><li>讨论 Ceph 分布式存储系统在视频会议字幕翻译中的应用与优化。</li></ul><p><strong>1.8 Learn Ceph — For Fun, For Real, For Free!</strong></p><ul><li>由 City Network 的 Florian Haas 介绍。</li><li>介绍了 Ceph 云学院课程更新及用户反馈征集。</li></ul><p><strong>1.9 Rebuilding a Faster OSD with Future</strong></p><ul><li>由 Red Hat 的 Kefu Chai 和 Radoslaw Zarzynski 介绍。</li><li>讨论了 Ceph Crimson 项目进展及未来方向。</li></ul><p><strong>1.10 Ceph Octopus Roadmap Planning series: RADOS</strong></p><ul><li>讨论了 Ceph Octopus 版本的更新计划，包括 EC 数据恢复、容量不足警告、自适应恢复设置等。</li></ul><h2 id="_2-技术发展和创新亮点" tabindex="-1">2. 技术发展和创新亮点 <a class="header-anchor" href="#_2-技术发展和创新亮点" aria-label="Permalink to &quot;2. 技术发展和创新亮点&quot;">​</a></h2><p><strong>2.1 Crimson 项目</strong></p><ul><li>针对 SSD 和 NVMe 接口的优化，提高 I/O 性能。</li><li>使用用户空间驱动器和无锁设计，避免锁竞争。</li><li>利用未来存储设备的并行处理能力。</li></ul><p><strong>2.2 Blue Store</strong></p><ul><li>基于 RocksDB 构建，提高 Ceph 的性能和效率。</li><li>支持持久内存，进一步提高性能。</li></ul><p><strong>2.3 CephFS</strong></p><ul><li>可扩展的分布式文件系统，支持 POSIX 兼容性。</li><li>高效的元数据管理，保证数据一致性。</li></ul><p><strong>2.4 RBD</strong></p><ul><li>基于 Ceph 的块存储，支持多种存储协议。</li><li>高效的存储和快照功能，保证数据可靠性。</li></ul><p><strong>2.5 Ceph 消息传递</strong></p><ul><li>基于 Seastar 构建，提高 Ceph 的性能和可扩展性。</li><li>支持异步编程模型，简化开发过程。</li></ul><h2 id="_3-重要的决策和里程碑" tabindex="-1">3. 重要的决策和里程碑 <a class="header-anchor" href="#_3-重要的决策和里程碑" aria-label="Permalink to &quot;3. 重要的决策和里程碑&quot;">​</a></h2><p><strong>3.1 Ceph Octopus 版本发布</strong></p><ul><li>发布了 Ceph Octopus 版本，包含多个新特性和改进。</li><li>引入了新的仪表盘、Orchestrator API、Rook 集成等。</li></ul><p><strong>3.2 Ceph 基金会成立</strong></p><ul><li>成立了 Ceph 基金会，旨在支持 Ceph 项目和社区发展。</li></ul><p><strong>3.3 CephCon 会议</strong></p><ul><li>举办了 CephCon 会议，分享了 Ceph 社区的最新进展和经验。</li></ul><h2 id="_4-社区贡献和合作情况" tabindex="-1">4. 社区贡献和合作情况 <a class="header-anchor" href="#_4-社区贡献和合作情况" aria-label="Permalink to &quot;4. 社区贡献和合作情况&quot;">​</a></h2><p><strong>4.1 贡献者数量增加</strong></p><ul><li>本季度 Ceph 社区贡献者数量持续增加，贡献了代码、文档和测试等。</li></ul><p><strong>4.2 合作项目增加</strong></p><ul><li>本季度 Ceph 社区与其他开源项目合作，共同推动存储技术的发展。</li></ul><p><strong>4.3 社区活动增加</strong></p><ul><li>本季度 Ceph 社区举办了多场线上和线下活动，促进了社区成员之间的交流。</li></ul><h2 id="_5-下一季度展望和计划" tabindex="-1">5. 下一季度展望和计划 <a class="header-anchor" href="#_5-下一季度展望和计划" aria-label="Permalink to &quot;5. 下一季度展望和计划&quot;">​</a></h2><p><strong>5.1 继续优化性能</strong></p><ul><li>针对 Crimson 项目进行性能测试和优化。</li><li>优化 Blue Store 和 CephFS 的性能。</li></ul><p><strong>5.2 持续改进功能</strong></p><ul><li>开发新的功能和特性，例如 CephFS 快照和克隆、RBD 支持多路径等。</li></ul><p><strong>5.3 加强社区建设</strong></p><ul><li>招募更多贡献者，并举办更多社区活动。</li><li>加强与其他开源项目的合作。</li></ul><p><strong>5.4 推动商业化发展</strong></p><ul><li>促进 Ceph 商业化发展，为用户提供更好的支持和服务。</li></ul><p><strong>结语</strong></p><p>Ceph 社区在 2019Q2 季度取得了显著进展，感谢所有贡献者的辛勤付出。相信在未来的发展中，Ceph 社区将取得更大的成就。</p>',58)])])}const d=e(o,[["render",a]]);export{g as __pageData,d as default};
